// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type ProcessGraphicProps = Record<string, any>;

const ProcessGraphic: React.FC<ProcessGraphicProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 8,
  backgroundImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/d5c026c86046400a946a1f652fc5725d.png",
  title = "Our Strategic Process",
  primaryColor = "#3b82f6",
  textColor = "#ffffff",
  steps = [
    {
      label: "Discovery",
      description: "Identifying core objectives and aligning on key deliverables before execution.",
    },
    {
      label: "Development",
      description: "Iterative building and prototyping with continuous feedback loops.",
    },
    {
      label: "Deployment",
      description: "Seamlessly launching and scaling the final product for end-users.",
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;
  const numSteps = Math.max(2, steps.length);

  // Title Animation
  const titleOpacity = interpolate(frame, [10, 30], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const titleY = interpolate(frame, [10, 30], [40, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      {/* Background Image Reference Layer */}
      {backgroundImage && (
        <AbsoluteFill style={{ opacity: 0.1 }}>
          <Img
            src={backgroundImage}
            style={{ width: "100%", height: "100%", objectFit: "cover" }}
          />
        </AbsoluteFill>
      )}

      {/* Main Content Container */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Title */}
        <h1
          style={{
            fontFamily: spaceGroteskFamily,
            fontSize: 64,
            fontWeight: 800,
            color: textColor,
            letterSpacing: "-0.02em",
            marginBottom: 120,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            transition: "none",
          }}
        >
          {title}
        </h1>

        {/* Process Graphic Container */}
        <div
          style={{
            position: "relative",
            width: width * 0.8,
            height: 350,
          }}
        >
          {/* Connecting Lines Layer */}
          <div
            style={{
              position: "absolute",
              top: 60, // Center of the 120px circles
              left: 0,
              right: 0,
              height: 6,
              transform: "translateY(-50%)",
            }}
          >
            {steps.map((_, idx) => {
              // Don't draw a line after the last step
              if (idx === steps.length - 1) return null;

              const stepDelay = 20 + idx * 40;
              const lineDelay = stepDelay + 15;
              const lineWidth = interpolate(frame, [lineDelay, lineDelay + 25], [0, 100], {
                extrapolateRight: "clamp",
                extrapolateLeft: "clamp",
              });

              return (
                <div
                  key={`line-track-${idx}`}
                  style={{
                    position: "absolute",
                    left: `${(idx / (numSteps - 1)) * 100}%`,
                    width: `${100 / (numSteps - 1)}%`,
                    height: "100%",
                    backgroundColor: `${textColor}15`, // Track color
                    transformOrigin: "left center",
                  }}
                >
                  <div
                    style={{
                      width: `${lineWidth}%`,
                      height: "100%",
                      backgroundColor: primaryColor,
                      transition: "none",
                    }}
                  />
                </div>
              );
            })}
          </div>

          {/* Nodes Layer */}
          {steps.map((step, idx) => {
            const stepDelay = 20 + idx * 40;
            const textDelay = stepDelay + 15;

            const circleScale = spring({
              frame: frame - stepDelay,
              fps,
              config: { damping: 14, stiffness: 120 },
            });
            const circleOp = interpolate(frame, [stepDelay, stepDelay + 10], [0, 1], {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
            });

            const textOp = interpolate(frame, [textDelay, textDelay + 20], [0, 1], {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
            });
            const textY = interpolate(frame, [textDelay, textDelay + 20], [20, 0], {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
            });

            return (
              <div
                key={`step-node-${idx}`}
                style={{
                  position: "absolute",
                  left: `${(idx / (numSteps - 1)) * 100}%`,
                  top: 0,
                  transform: "translateX(-50%)",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  width: 380,
                }}
              >
                {/* Process Circle */}
                <div
                  style={{
                    width: 120,
                    height: 120,
                    borderRadius: "50%",
                    backgroundColor: finalBgColor,
                    border: `6px solid ${primaryColor}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    transform: `scale(${Math.max(0, circleScale)})`,
                    opacity: circleOp,
                    zIndex: 10,
                    transition: "none",
                    boxShadow: `0 0 40px ${primaryColor}20`,
                  }}
                >
                  <span
                    style={{
                      fontFamily: spaceGroteskFamily,
                      fontSize: 52,
                      fontWeight: 700,
                      color: textColor,
                    }}
                  >
                    {idx + 1}
                  </span>
                </div>

                {/* Text Content */}
                <div
                  style={{
                    marginTop: 40,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    opacity: textOp,
                    transform: `translateY(${textY}px)`,
                    transition: "none",
                  }}
                >
                  <h3
                    style={{
                      fontFamily: spaceGroteskFamily,
                      fontSize: 36,
                      fontWeight: 700,
                      color: textColor,
                      margin: 0,
                      textAlign: "center",
                    }}
                  >
                    {step.label}
                  </h3>
                  <p
                    style={{
                      fontFamily: interFamily,
                      fontSize: 22,
                      color: textColor,
                      opacity: 0.75,
                      textAlign: "center",
                      marginTop: 16,
                      lineHeight: 1.5,
                      margin: 0,
                      maxWidth: "90%",
                    }}
                  >
                    {step.description}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ProcessGraphic;